/* test_liblscp.c — consumer test for liblscp 1.0.1
 *
 * Compiled and linked against the *installed* package (headers under
 * include/lscp/, artifact liblscp.so) and executed by test_package/conanfile.py.
 *
 * It exercises four independent behaviours of the library, all decided by
 * assertions that feed the process exit code:
 *   1. the version strings generated by upstream's configure_file() of
 *      lscp/version.h.cmake (also proves the `git describe` version override in
 *      the top CMakeLists.txt stayed inert for a tarball build);
 *   2. the event <-> text table in src/event.c, including its case-insensitive
 *      from_text() path and the NULL/unknown fallbacks;
 *   3. the NULL-handle argument contracts of the client API;
 *   4. a real LSCP transaction over a loopback socket against an in-process fake
 *      server, covering the request/response and error parsing in src/common.c
 *      (lscp_client_call) plus lscp_client_set_timeout()/get_events()/destroy();
 *   5. the joinable-worker teardown that the OHOS patch rewrites: the public
 *      thread API and lscp_socket_agent_free(), which is what src/client.c:231
 *      (event service thread) goes through on close.  Both cases are timed so a
 *      cancellation that fails to terminate the worker shows up as a failed
 *      assertion instead of a silent hang.
 */
#include <lscp/client.h>
#include <lscp/socket.h>
#include <lscp/thread.h>

#include <errno.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>

static int g_assertions = 0;
static int g_failures   = 0;

#define CHECK(cond)                                                       \
    do {                                                                  \
        ++g_assertions;                                                   \
        if (!(cond)) {                                                    \
            ++g_failures;                                                 \
            printf("FAIL %s:%d: %s (errno=%d %s)\n",                      \
                   __FILE__, __LINE__, #cond, errno, strerror(errno));    \
        }                                                                 \
    } while (0)

/* The client API refuses a NULL callback (src/client.c: lscp_client_create
 * returns NULL when pfnCallback == NULL), so a real one must be supplied. */
static lscp_status_t client_callback (lscp_client_t *pClient, lscp_event_t event,
                                     const char *pchData, int cchData, void *pvData)
{
    (void) pClient; (void) event; (void) pchData; (void) cchData; (void) pvData;
    return LSCP_OK;
}

/* ---- in-process fake LSCP server (loopback, single connection) ---- */

#define REPLY_OK_VOLUME   "OK[0.85]\r\n"
#define REPLY_OK_PLAIN    "OK\r\n"
#define REPLY_ERR         "ERR:400:bogus command\r\n"

static void *peer_thread (void *arg)
{
    int  lsock = *(int *) arg;
    char buf[512];

    int csock = accept(lsock, NULL, NULL);
    if (csock < 0) {
        printf("peer: accept failed errno=%d\n", errno);
        return NULL;
    }

    for (;;) {
        ssize_t n = recv(csock, buf, sizeof(buf) - 1, 0);
        if (n <= 0)
            break;
        buf[n] = '\0';

        const char *reply;
        size_t      len;
        if (strstr(buf, "GET MASTER_VOLUME") != NULL) {
            reply = REPLY_OK_VOLUME;
        } else if (strstr(buf, "SET MASTER_VOLUME") != NULL) {
            reply = REPLY_OK_PLAIN;
        } else {
            reply = REPLY_ERR;
        }
        len = strlen(reply);
        if (send(csock, reply, len, 0) != (ssize_t) len) {
            printf("peer: send failed errno=%d\n", errno);
            break;
        }
    }

    close(csock);
    return NULL;
}

static int make_listener (int *port)
{
    struct sockaddr_in addr;

    int lsock = socket(AF_INET, SOCK_STREAM, 0);
    if (lsock < 0)
        return -1;

    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_port        = 0;                    /* ephemeral */
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (bind(lsock, (struct sockaddr *) &addr, sizeof(addr)) != 0) {
        close(lsock);
        return -1;
    }

    socklen_t alen = sizeof(addr);
    if (getsockname(lsock, (struct sockaddr *) &addr, &alen) != 0) {
        close(lsock);
        return -1;
    }
    *port = ntohs(addr.sin_port);

    if (listen(lsock, 1) != 0) {
        close(lsock);
        return -1;
    }
    return lsock;
}

/* ---- workers for the thread-teardown cases (section 5) ----
 *
 * Every threaded user of this library runs through one chain:
 *   src/client.c:231  lscp_socket_agent_start(&pClient->evt, _lscp_client_evt_proc, pClient, 0)
 *   src/socket.c:219  -> lscp_thread_create()          joinable worker (iDetach = 0)
 *   src/socket.c:248  lscp_socket_agent_free()         -> lscp_thread_destroy()
 *   src/thread.c      lscp_thread_destroy()            -> cancel(), then join()
 * While an event service thread waits for the next LSCP event it does not
 * return on its own, which is exactly the case below: if cancellation only
 * *claims* success, lscp_thread_join() waits forever.  So the teardown is
 * timed and its return code asserted.
 */
static void worker_never_returns (void *pvData)
{
    (void) pvData;
    for (;;)
        sleep(1);
}

static int g_worker_ran = 0;

static void worker_returns_at_once (void *pvData)
{
    (void) pvData;
    g_worker_ran = 1;
}

static long elapsed_ms (const struct timespec *t0, const struct timespec *t1)
{
    return (long) ((t1->tv_sec - t0->tv_sec) * 1000 +
                   (t1->tv_nsec - t0->tv_nsec) / 1000000);
}

#define TEARDOWN_BUDGET_MS 5000

int main (void)
{
    /* ---- 1. generated version strings ---- */
    const char *pkg = lscp_client_package();
    const char *ver = lscp_client_version();
    const char *bld = lscp_client_build();
    CHECK(pkg != NULL && strcmp(pkg, "liblscp") == 0);
    CHECK(ver != NULL && strcmp(ver, "1.0.1") == 0);
    CHECK(bld != NULL && strcmp(bld, "1.0.1") == 0);
    printf("version: package=%s version=%s build=%s\n",
           pkg ? pkg : "(null)", ver ? ver : "(null)", bld ? bld : "(null)");

    /* ---- 2. event <-> text table ---- */
    static const struct {
        lscp_event_t event;
        const char  *text;
    } table[] = {
        { LSCP_EVENT_CHANNEL_COUNT,             "CHANNEL_COUNT"             },
        { LSCP_EVENT_VOICE_COUNT,               "VOICE_COUNT"               },
        { LSCP_EVENT_STREAM_COUNT,              "STREAM_COUNT"              },
        { LSCP_EVENT_BUFFER_FILL,               "BUFFER_FILL"               },
        { LSCP_EVENT_CHANNEL_INFO,              "CHANNEL_INFO"              },
        { LSCP_EVENT_TOTAL_VOICE_COUNT,         "TOTAL_VOICE_COUNT"         },
        { LSCP_EVENT_AUDIO_OUTPUT_DEVICE_COUNT, "AUDIO_OUTPUT_DEVICE_COUNT" },
        { LSCP_EVENT_AUDIO_OUTPUT_DEVICE_INFO,  "AUDIO_OUTPUT_DEVICE_INFO"  },
        { LSCP_EVENT_MIDI_INPUT_DEVICE_COUNT,   "MIDI_INPUT_DEVICE_COUNT"   },
        { LSCP_EVENT_MIDI_INPUT_DEVICE_INFO,    "MIDI_INPUT_DEVICE_INFO"    },
        { LSCP_EVENT_MIDI_INSTRUMENT_MAP_COUNT, "MIDI_INSTRUMENT_MAP_COUNT" },
        { LSCP_EVENT_MIDI_INSTRUMENT_MAP_INFO,  "MIDI_INSTRUMENT_MAP_INFO"  },
        { LSCP_EVENT_MIDI_INSTRUMENT_COUNT,     "MIDI_INSTRUMENT_COUNT"     },
        { LSCP_EVENT_MIDI_INSTRUMENT_INFO,      "MIDI_INSTRUMENT_INFO"      },
        { LSCP_EVENT_MISCELLANEOUS,             "MISCELLANEOUS"             },
        { LSCP_EVENT_CHANNEL_MIDI,              "CHANNEL_MIDI"              },
        { LSCP_EVENT_DEVICE_MIDI,               "DEVICE_MIDI"               },
    };
    const size_t ntable = sizeof(table) / sizeof(table[0]);
    CHECK(ntable == 17);

    for (size_t i = 0; i < ntable; ++i) {
        const char *text = lscp_event_to_text(table[i].event);
        CHECK(text != NULL && strcmp(text, table[i].text) == 0);
        CHECK(lscp_event_from_text(table[i].text) == table[i].event);
    }
    CHECK(lscp_event_to_text(LSCP_EVENT_NONE) == NULL);
    CHECK(lscp_event_from_text(NULL) == LSCP_EVENT_NONE);
    CHECK(lscp_event_from_text("LSCP_NO_SUCH_EVENT") == LSCP_EVENT_NONE);
    /* from_text() uses strcasecmp(): the lower-case spelling must resolve. */
    CHECK(lscp_event_from_text("channel_count") == LSCP_EVENT_CHANNEL_COUNT);

    /* ---- 3. NULL-handle contracts ---- */
    CHECK(lscp_client_get_errno(NULL)  == -1);
    CHECK(lscp_client_get_result(NULL) == NULL);
    CHECK(lscp_client_get_timeout(NULL) == -1);
    CHECK(lscp_client_query(NULL, "GET CHANNELS\r\n") == LSCP_FAILED);
    CHECK(lscp_client_get_events(NULL) == LSCP_EVENT_NONE);

    /* ---- 4a. connecting to a port nobody listens on must fail ---- */
    int dead_port = 0;
    int probe = make_listener(&dead_port);
    CHECK(probe >= 0);
    if (probe >= 0)
        close(probe);                       /* nothing listens on dead_port now */
    CHECK(lscp_client_create("127.0.0.1", dead_port, client_callback, NULL) == NULL);

    /* ---- 4b. a real transaction against the fake server ---- */
    int port   = 0;
    int lsock  = make_listener(&port);
    CHECK(lsock >= 0);
    CHECK(port > 0);

    if (lsock >= 0) {
        pthread_t tid;
        CHECK(pthread_create(&tid, NULL, peer_thread, &lsock) == 0);

        lscp_client_t *client = lscp_client_create("127.0.0.1", port,
                                                   client_callback, NULL);
        CHECK(client != NULL);

        if (client != NULL) {
            /* Default timeout is 0 ms, which makes the internal select()
             * non-blocking; the API contract is to set it explicitly. */
            CHECK(lscp_client_set_timeout(client, 5000) == LSCP_OK);
            CHECK(lscp_client_get_timeout(client) == 5000);
            CHECK(lscp_client_get_events(client) == LSCP_EVENT_NONE);

            CHECK(lscp_client_query(client, "GET MASTER_VOLUME\r\n") == LSCP_OK);
            const char *res = lscp_client_get_result(client);
            CHECK(res != NULL && strcmp(res, "0.85") == 0);
            CHECK(lscp_client_get_errno(client) == 0);

            /* "OK\r\n" (no bracketed payload) is accumulated verbatim. */
            CHECK(lscp_client_query(client, "SET MASTER_VOLUME 0.5\r\n") == LSCP_OK);
            res = lscp_client_get_result(client);
            CHECK(res != NULL && strcmp(res, "OK") == 0);

            /* ERR: replies become LSCP_ERROR with errno = code + 100. */
            CHECK(lscp_client_query(client, "LIST BOGUS\r\n") == LSCP_ERROR);
            CHECK(lscp_client_get_errno(client) == 500);
            res = lscp_client_get_result(client);
            CHECK(res != NULL && strcmp(res, "bogus command") == 0);

            CHECK(lscp_client_destroy(client) == LSCP_OK);
        }

        close(lsock);
        pthread_join(tid, NULL);
    }

    /* ---- 5. joinable worker teardown: the OHOS cancellation path ---- */

    /* 5a. public thread API, worker still blocked: cancel() must terminate it
     *     and join() must then reclaim it. */
    {
        lscp_thread_t *pThr = lscp_thread_create(worker_never_returns, NULL, 0);
        CHECK(pThr != NULL);
        if (pThr != NULL) {
            struct timespec t0, t1;
            long ms;
            int ret_cancel, ret_join;

            usleep(200 * 1000);            /* let the worker reach sleep(1) */
            clock_gettime(CLOCK_MONOTONIC, &t0);
            ret_cancel = lscp_thread_cancel(pThr);
            ret_join   = lscp_thread_join(pThr);
            clock_gettime(CLOCK_MONOTONIC, &t1);
            ms = elapsed_ms(&t0, &t1);

            CHECK(ret_cancel == LSCP_OK);
            CHECK(ret_join == LSCP_OK);
            CHECK(ms < TEARDOWN_BUDGET_MS);
            printf("thread cancel+join (live worker): ret=%d/%d elapsed_ms=%ld\n",
                   ret_cancel, ret_join, ms);
            free(pThr);   /* lscp_thread_destroy() is the only free() in the library */
        }
    }

    /* 5b. worker that already returned by itself: destroy() must still reclaim
     *     it promptly rather than block in the join. */
    {
        lscp_thread_t *pThr = lscp_thread_create(worker_returns_at_once, NULL, 0);
        CHECK(pThr != NULL);
        if (pThr != NULL) {
            struct timespec t0, t1;
            long ms;
            int ret_destroy;

            usleep(200 * 1000);
            clock_gettime(CLOCK_MONOTONIC, &t0);
            ret_destroy = lscp_thread_destroy(pThr);
            clock_gettime(CLOCK_MONOTONIC, &t1);
            ms = elapsed_ms(&t0, &t1);

            CHECK(ms < TEARDOWN_BUDGET_MS);
            CHECK(g_worker_ran == 1);
            printf("thread destroy (natural exit): ret=%d elapsed_ms=%ld\n",
                   ret_destroy, ms);
        }
    }

    /* 5c. the library's own caller: lscp_socket_agent_free(), i.e. what
     *     lscp_client_destroy() does to a running event service thread. */
    {
        lscp_socket_agent_t agent;
        int afd = socket(AF_INET, SOCK_STREAM, 0);

        CHECK(afd >= 0);
        if (afd >= 0) {
            struct timespec t0, t1;
            long ms;
            int ret_start, ret_free;

            lscp_socket_agent_init(&agent, afd, NULL, 0);
            ret_start = lscp_socket_agent_start(&agent, worker_never_returns, NULL, 0);
            CHECK(ret_start == LSCP_OK);
            if (ret_start == LSCP_OK) {
                usleep(200 * 1000);
                clock_gettime(CLOCK_MONOTONIC, &t0);
                ret_free = lscp_socket_agent_free(&agent);
                clock_gettime(CLOCK_MONOTONIC, &t1);
                ms = elapsed_ms(&t0, &t1);
                CHECK(ret_free == LSCP_OK);
                CHECK(ms < TEARDOWN_BUDGET_MS);
                printf("socket agent free (live worker): ret=%d elapsed_ms=%ld\n",
                       ret_free, ms);
            } else {
                close(afd);
            }
        }
    }

    printf("liblscp consumer test: %d assertions, %d failures\n",
           g_assertions, g_failures);
    if (g_failures == 0) {
        printf("RESULT: PASS\n");
        return 0;
    }
    printf("RESULT: FAIL\n");
    return 1;
}
